import{_ as l,o as a,c as t,aw as i}from"./chunks/framework.DLufY-ao.js";const o="/workbook/assets/mvc.D0LMbq5t.png",_=JSON.parse('{"title":"MVC","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/architecture/mvc/mvc.md","filePath":"wiki/dev-commit/theory/architecture/mvc/mvc.md"}'),r={name:"wiki/dev-commit/theory/architecture/mvc/mvc.md"};function c(n,e,s,d,m,h){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="mvc" tabindex="-1">MVC <a class="header-anchor" href="#mvc" aria-label="Permalink to &quot;MVC&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>Model-View-Controller (MVC)</strong> («Модель-Представление/Вид-Контроллер») - схема разделения данных приложения, пользовательского интерфейса и управляющей логики на три отдельных компонента: модель, представление и контроллер - таким образом, что модификация каждого компонента может осуществляться независимо</li></ul></div><ul><li>MVC позволяет следовать принципу разделения ответственностей и способствует написанию чистого кода</li><li>MVC - это модель черного ящика. Есть входы (действия пользователя), есть выходы (это реакция интерфейса), есть внутренняя логика (модель)</li><li>Controller полностью отделен от View</li></ul><img src="'+o+'" style="width:550px;"><h2 id="структура" tabindex="-1">Структура <a class="header-anchor" href="#структура" aria-label="Permalink to &quot;Структура&quot;">​</a></h2><h3 id="_1-модель-model" tabindex="-1">1. Модель (Model) <a class="header-anchor" href="#_1-модель-model" aria-label="Permalink to &quot;1. Модель (Model)&quot;">​</a></h3><ul><li><strong>Модель (Model)</strong> - данные, методы для работы с данными, изменения и обновления данных</li><li>Реагирует на команды контроллера, изменяя своё состояние (бизнес-логика: просчитывание данных, операций, работа с БД)</li><li>Модель - работа с данными (выполнение ajax-операций, взаимодействие с сервером). Модель занята работой с JSON или объектами, которые поступают с сервера</li><li>Модель - это не слой взаимодействия с бекендом, это, скорее, аналог view model из mvvm</li></ul><h3 id="_2-представление-view" tabindex="-1">2. Представление (View) <a class="header-anchor" href="#_2-представление-view" aria-label="Permalink to &quot;2. Представление (View)&quot;">​</a></h3><ul><li><strong>Представление (View)</strong> - отображение данных модели пользователю</li><li>Реагирует на изменения модели</li><li>Взаимодействие с DOM. Представление может выполнять подключение обработчиков событий пользовательского интерфейса, но обработку событий - выполняет контроллер</li></ul><h3 id="_3-контроллер-controller" tabindex="-1">3. Контроллер (Controller) <a class="header-anchor" href="#_3-контроллер-controller" aria-label="Permalink to &quot;3. Контроллер (Controller)&quot;">​</a></h3><ul><li><strong>Контроллер (Controller)</strong> - обработка событий. Интерпретирует действия пользователя (например, щелчек по кнопке или нажатие клавиши на клавиатуре), оповещая модель о необходимости изменений (берет данные из view и передает в model - запускает model. Бизнес-логика, обработка данных из БД)</li><li>Логика клиентских приложений может быть реализована в контроллере</li></ul>',12)])])}const v=l(r,[["render",c]]);export{_ as __pageData,v as default};
